// ***************
// Filename: pwm_regs.h
// Author: FPGA Cores 4 U
// Description: C header of the pwm register map (generated by regmap_gen.py): byte offsets, reset values,
//   field shifts and masks.
// Date: 2026-10-12
#ifndef PWM_REGS_H
#define PWM_REGS_H
#define PWM_REGS_ID_OFFSET 0x00u
#define PWM_REGS_VERSION_OFFSET 0x04u
#define PWM_REGS_DATE_OFFSET 0x08u
#define PWM_REGS_ID_VALUE 0x50574D54u   /* "PWMT" */
#define PWM_REGS_CTRL_OFFSET 0x10u   /* RW */
#define PWM_REGS_CTRL_RESET 0x00000000u
#define PWM_REGS_CTRL_EN_SHIFT 0u
#define PWM_REGS_CTRL_EN_MASK 0x00000001u
#define PWM_REGS_CTRL_CENTER_SHIFT 1u
#define PWM_REGS_CTRL_CENTER_MASK 0x00000002u
#define PWM_REGS_CTRL_COMPLEMENTARY_SHIFT 2u
#define PWM_REGS_CTRL_COMPLEMENTARY_MASK 0x00000004u
#define PWM_REGS_PERIOD_OFFSET 0x14u   /* RW */
#define PWM_REGS_PERIOD_RESET 0x00000063u
#define PWM_REGS_PRESCALE_OFFSET 0x18u   /* RW */
#define PWM_REGS_PRESCALE_RESET 0x00000000u
#define PWM_REGS_DEADTIME_OFFSET 0x1Cu   /* RW */
#define PWM_REGS_DEADTIME_RESET 0x00000000u
#define PWM_REGS_INVERT_OFFSET 0x20u   /* RW */
#define PWM_REGS_INVERT_RESET 0x00000000u
#define PWM_REGS_DUTY_OFFSET 0x24u   /* RW array, stride 4 */
#define PWM_REGS_DUTY_STRIDE 4u
#define PWM_REGS_DUTY_RESET 0x00000000u
#endif /* PWM_REGS_H */
